Optimal Solution (O(N) Time, O(1) Extra Space):

C++ Implementation:
```cpp
#include <iostream>
#include <string>
using namespace std;

string compressString(const string &s) {
    if (s.empty()) return "";
    string result = "";
    int n = s.length();
    for (int i = 0; i < n; ) {
        char ch = s[i];
        int count = 0;
        while (i < n && s[i] == ch) {
            count++;
            i++;
        }
        result += ch + to_string(count);
    }
    return result;
}

int main() {
    string s = "aabbbbeeeeffggg";
    cout << compressString(s) << endl; // Output: a2b4e4f2g3
    return 0;
}
```

Python Implementation:
```python
def compress_string(s: str) -> str:
    if not s:
        return ""
    result = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        count = 0
        while i < n and s[i] == ch:
            count += 1
            i += 1
        result.append(f"{ch}{count}")
    return "".join(result)
```

Optimal Solution (O(M * N) Time, O(1) Auxiliary Space):

Approach:
Maintain four boundaries: `top = 0`, `bottom = m - 1`, `left = 0`, `right = n - 1`.
Loop while `top <= bottom` and `left <= right`:
1. Traverse from left to right along row `top`, then increment `top`.
2. Traverse from top to bottom along column `right`, then decrement `right`.
3. If `top <= bottom`, traverse from right to left along row `bottom`, then decrement `bottom`.
4. If `left <= right`, traverse from bottom to top along column `left`, then increment `left`.

C++ Code:
```cpp
#include <vector>
using namespace std;

vector<int> spiralOrder(vector<vector<int>>& matrix) {
    vector<int> ans;
    if (matrix.empty()) return ans;
    int top = 0, bottom = matrix.size() - 1;
    int left = 0, right = matrix[0].size() - 1;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) ans.push_back(matrix[top][c]);
        top++;
        for (int r = top; r <= bottom; r++) ans.push_back(matrix[r][right]);
        right--;
        if (top <= bottom) {
            for (int c = right; c >= left; c--) ans.push_back(matrix[bottom][c]);
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; r--) ans.push_back(matrix[r][left]);
            left++;
        }
    }
    return ans;
}
```
Time Complexity: O(M * N) where every matrix cell is visited exactly once.
Space Complexity: O(1) auxiliary space.

