C++ Code:
```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

void printFrequencies(const vector<int>& nums) {
    unordered_map<int, int> freq;
    vector<int> order;

    for (int x : nums) {
        if (freq[x] == 0) {
            order.push_back(x); // preserve first appearance order
        }
        freq[x]++;
    }

    for (int x : order) {
        cout << x << " occurs " << freq[x] << (freq[x] == 1 ? " time" : " times") << endl;
    }
}
```

