#include <iostream>
using namespace std;

void solve(int v, int w) {
    if (w < 2 || w % 2 != 0 || v < 1 || w < 2 * v || w > 4 * v) {
        cout << "INVALID INPUT" << endl;
        return;
    }
    int fw = (w - 2 * v) / 2;
    int tw = v - fw;
    cout << "TW = " << tw << ", FW = " << fw << endl;
}
```

Optimal Solution (O(N) Time, O(k) Space):

Key Insight:
If (a + b) % k == 0, then:
- Either a % k == 0 and b % k == 0 (meaning count of elements with remainder 0 must be even).
- Or (a % k) + (b % k) == k, meaning frequency of remainder r must equal frequency of remainder (k - r).
- If k is even, elements with remainder k/2 must also occur an even number of times.

C++ Code:
```cpp
#include <vector>
#include <unordered_map>
using namespace std;

bool canPairs(vector<int>& nums, int k) {
    if (nums.size() % 2 != 0) return false;
    unordered_map<int, int> remFreq;
    for (int x : nums) {
        int rem = ((x % k) + k) % k; // handle negative values
        remFreq[rem]++;
    }
    for (auto &p : remFreq) {
        int rem = p.first;
        int count = p.second;
        if (rem == 0) {
            if (count % 2 != 0) return false;
        } else if (2 * rem == k) {
            if (count % 2 != 0) return false;
        } else {
            if (remFreq[k - rem] != count) return false;
        }
    }
    return true;
}
```
Time Complexity: O(N) single pass to count remainders.

Optimal Solution (Handling 32-bit integer limits without 64-bit casting):

C++ Code:
```cpp
#include <climits>
using namespace std;

int reverse(int x) {
    int rev = 0;
    while (x != 0) {
        int pop = x % 10;
        x /= 10;

        // Check for positive overflow
        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) return 0;
        // Check for negative underflow
        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) return 0;

        rev = rev * 10 + pop;
    }
    return rev;
}
```
Time Complexity: O(log10(x)) ~ 10 operations max.
Space Complexity: O(1).

Optimal Solution (O(N) Time, O(1) Space):

Key Strategy:
1. Compute total sum of all elements in the array in the first pass.
2. Maintain `left_sum = 0`.
3. Traverse the array: for index `i`, `right_sum = total_sum - left_sum - nums[i]`.
4. If `left_sum == right_sum`, return `i`.
5. Otherwise, `left_sum += nums[i]`.

C++ Code:
```cpp
#include <vector>
#include <numeric>
using namespace std;

int findEquilibriumIndex(const vector<int>& nums) {
    long long total_sum = 0;
    for (int x : nums) total_sum += x;

    long long left_sum = 0;
    for (int i = 0; i < nums.size(); i++) {
        long long right_sum = total_sum - left_sum - nums[i];
        if (left_sum == right_sum) return i;
        left_sum += nums[i];
    }
    return -1;
}
```

Optimal Solution (O(N) Time, O(1) Auxiliary Space since alphabet size is bounded to 26):

C++ Code:
```cpp
#include <string>
#include <vector>
using namespace std;

bool isAnagram(string s, string t) {
    if (s.length() != t.length()) return false;
    vector<int> count(26, 0);
    for (int i = 0; i < s.length(); i++) {
        count[s[i] - 'a']++;
        count[t[i] - 'a']--;
    }
    for (int c : count) {
        if (c != 0) return false;
    }
    return true;
}
```
Time Complexity: O(N)
Space Complexity: O(1) with 26 integer slots.

Optimal Solution (Two-Pointer Technique):

C++ Code:
```cpp
#include <vector>
using namespace std;

void moveZeroes(vector<int>& nums) {
    int insertPos = 0;
    // Move all non-zero elements forward
    for (int i = 0; i < nums.size(); i++) {
        if (nums[i] != 0) {
            nums[insertPos++] = nums[i];
        }
    }
    // Fill remaining positions with zeroes
    while (insertPos < nums.size()) {
        nums[insertPos++] = 0;
    }
}
```
Time Complexity: O(N) where N is array length.
Space Complexity: O(1) in-place modification.

Optimal Solution:

C++ Code:
```cpp
#include <iostream>
#include <cmath>
using namespace std;

bool isArmstrong(int n) {
    if (n < 0) return false;
    int temp = n;
    int digits = 0;
    while (temp > 0) {
        digits++;
        temp /= 10;
    }

    temp = n;
    long long sum = 0;
    while (temp > 0) {
        int d = temp % 10;
        sum += round(pow(d, digits));
        temp /= 10;
    }
    return sum == n;
}
```
